package ai.applypilot.resume;
import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.util.*;
@RestController @RequestMapping("/api/resumes") public class ResumeController {
 private final ResumeService service; public ResumeController(ResumeService s){service=s;} private UUID owner(Authentication a){return (UUID)a.getPrincipal();}
 @GetMapping public List<ResumeService.ResumeDto> list(Authentication a){return service.list(owner(a));}
 @GetMapping("/{id}/versions") public List<ResumeService.VersionDto> versions(Authentication a,@PathVariable UUID id){return service.versions(owner(a),id);}
 @PostMapping("/{id}/versions/{version}/review") @ResponseStatus(HttpStatus.CREATED) public ResumeService.VersionDto review(Authentication a,@PathVariable UUID id,@PathVariable int version,@jakarta.validation.Valid @RequestBody ResumeService.ResumeReview review){return service.saveReview(owner(a),id,version,review);}
 @PostMapping("/{id}/versions/{version}/export") @ResponseStatus(HttpStatus.CREATED) public ResumeService.VersionDto export(Authentication a,@PathVariable UUID id,@PathVariable int version,@RequestParam String format,@RequestParam(required=false) List<UUID> certificationIds){return service.export(owner(a),id,version,format,certificationIds==null?List.of():certificationIds);}
 @PostMapping("/{id}/versions/{version}/tailor") @ResponseStatus(HttpStatus.CREATED) public ResumeService.VersionDto tailor(Authentication a,@PathVariable UUID id,@PathVariable int version,@jakarta.validation.Valid @RequestBody TailorRequest req){return service.tailor(owner(a),id,version,req);}
 @GetMapping("/{id}/versions/{version}/download") public ResponseEntity<byte[]> downloadVersion(Authentication a,@PathVariable UUID id,@PathVariable int version){var d=service.downloadVersion(owner(a),id,version);var media=d.extension().equals("pdf")?MediaType.APPLICATION_PDF:MediaType.parseMediaType("application/vnd.openxmlformats-officedocument.wordprocessingml.document");return ResponseEntity.ok().contentType(media).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\"resume-v"+version+"."+d.extension()+"\"").body(d.bytes());}
 @PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @ResponseStatus(HttpStatus.CREATED) public ResumeService.ResumeDto upload(Authentication a,@RequestPart("file") MultipartFile f){var r=service.upload(owner(a),f);return new ResumeService.ResumeDto(r.getId(),r.getFilename(),r.getSha256(),r.getSize(),r.getCreatedAt());}
 @GetMapping("/{id}/download") public ResponseEntity<byte[]> download(Authentication a,@PathVariable UUID id){byte[] data=service.download(owner(a),id);return ResponseEntity.ok().contentType(MediaType.APPLICATION_OCTET_STREAM).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\"resume\"").body(data);}
}
